class Solution {public int solve(int[] values,long limit){ArrayDeque<Integer> hi=new ArrayDeque<>(),lo=new ArrayDeque<>();int left=0,best=0;for(int right=0;right<values.length;right++){while(!hi.isEmpty()&&values[hi.peekLast()]<=values[right])hi.removeLast();while(!lo.isEmpty()&&values[lo.peekLast()]>=values[right])lo.removeLast();hi.addLast(right);lo.addLast(right);while((long)values[hi.peekFirst()]-values[lo.peekFirst()]>limit){left++;if(hi.peekFirst()<left)hi.removeFirst();if(lo.peekFirst()<left)lo.removeFirst();}best=Math.max(best,right-left+1);}return best;}}